```sql
/* Выбираем молекулы, у которых есть одинарные связи (bond_type = '-') */
/* и которые не являются канцерогенными (label = '-') */
/* Возвращаем топ-3 уникальных molecule_id в алфавитном порядке */
SELECT DISTINCT m."molecule_id"
FROM "molecule" m
JOIN "bond" b ON b."molecule_id" = m."molecule_id"
WHERE m."label" = '-'
  AND b."bond_type" = '-'
ORDER BY m."molecule_id"
LIMIT 3;
```

```sql
/* Вычисляем процент молекул, содержащих водород (element = 'h'), среди канцерогенных молекул (label = '+') */
SELECT
    /* Доля молекул с водородом среди канцерогенных, умноженная на 100 */
    (COUNT(DISTINCT CASE WHEN a."element" = 'h' THEN m."molecule_id" END)::numeric
     / NULLIF(COUNT(DISTINCT m."molecule_id"), 0)) * 100.0 AS percentage
FROM "molecule" m
/* Соединяем молекулы с атомами */
JOIN "atom" a
    ON a."molecule_id" = m."molecule_id"
/* Ограничиваем канцерогенными молекулами */
WHERE m."label" = '+';
```

