```sql
/* Доля карт Story Spotlight без текстового блока (istextless = 0) от общего числа карт */
SELECT
    /* Процент: карты Story Spotlight с текстовым блоком / все карты * 100 */
    (COUNT(*) FILTER (WHERE "isstoryspotlight" = 1 AND "istextless" = 0)::numeric
     / NULLIF(COUNT(*), 0)) * 100 AS percentage,
    /* Список ID таких карт */
    ARRAY_AGG("id" ORDER BY "id") FILTER (WHERE "isstoryspotlight" = 1 AND "istextless" = 0) AS story_spotlight_ids
FROM "cards";
```

```sql
/* Доля карт без силы (power IS NULL или '*'), у которых язык французский */
SELECT
    /* Процент: французские карты без силы / все карты без силы * 100 */
    (COUNT(CASE WHEN fd."language" = 'French' THEN 1 END)::numeric
     / NULLIF(COUNT(*), 0)::numeric) * 100 AS percentage
FROM "foreign_data" fd
WHERE fd."power" IS NULL OR fd."power" = '*';
