```sql
/* Соотношение количества супергероев по полу: male / female */
SELECT
    /* Числитель: количество male (gender = 'Male') */
    SUM(CASE WHEN g."gender" = 'Male' THEN 1 ELSE 0 END)::numeric
    /
    /* Знаменатель: количество female (gender = 'Female') */
