/* Находим бюджет с минимальным остатком (remaining) */
WITH lowest_budget AS (
    SELECT "budget_id"
    FROM "budget"
    ORDER BY "remaining" ASC
    LIMIT 1
)
/* Выводим описания расходов, относящихся к этому бюджету */
